from pysat.solvers import Glucose3
import itertools

N = 24
solver = Glucose3()

# Variables for edges: e_{i,j} for i < j
def var(i, j):
    if i > j:
        i, j = j, i
    return i * N + j + 1

# Degree constraints: exactly 3
for i in range(N):
    edges_i = [var(i, j) for j in range(N) if i != j]
    # At least 3
    for comb in itertools.combinations(edges_i, len(edges_i) - 3 + 1):
        solver.add_clause([c for c in comb])
    # At most 3
    for comb in itertools.combinations(edges_i, 3 + 1):
        solver.add_clause([-c for c in comb])

# Girth >= 7: no cycles of length 3, 4, 5, 6
# We can just enumerate all paths of length 2, 3, 4, 5 and ensure they don't close.
# Actually, enumerating all cycles of length up to 6 is feasible.
# 3-cycles
for i, j, k in itertools.combinations(range(N), 3):
    solver.add_clause([-var(i, j), -var(j, k), -var(k, i)])

# 4-cycles
for c in itertools.combinations(range(N), 4):
    for p in itertools.permutations(c):
        if p[0] < p[1] and p[0] < p[2] and p[0] < p[3] and p[1] < p[3]:
            solver.add_clause([-var(p[0], p[1]), -var(p[1], p[2]), -var(p[2], p[3]), -var(p[3], p[0])])

# 5-cycles
for c in itertools.combinations(range(N), 5):
    for p in itertools.permutations(c):
        if p[0] == min(p) and p[1] < p[4]:
            solver.add_clause([-var(p[0], p[1]), -var(p[1], p[2]), -var(p[2], p[3]), -var(p[3], p[4]), -var(p[4], p[0])])

# 6-cycles
for c in itertools.combinations(range(N), 6):
    for p in itertools.permutations(c):
        if p[0] == min(p) and p[1] < p[5]:
            solver.add_clause([-var(p[0], p[1]), -var(p[1], p[2]), -var(p[2], p[3]), -var(p[3], p[4]), -var(p[4], p[5]), -var(p[5], p[0])])

print("Solving...")
if solver.solve():
    print("SAT")
    model = solver.get_model()
    edges = []
    for i in range(N):
        for j in range(i+1, N):
            if model[var(i, j) - 1] > 0:
                edges.extend([i, j])
    print(edges)
else:
    print("UNSAT")

from pysat.solvers import Glucose3
import itertools
import collections

N = 24
solver = Glucose3()

def var(i, j):
    if i > j:
        i, j = j, i
    return i * N + j + 1

# Degree constraints: exactly 3
for i in range(N):
    edges_i = [var(i, j) for j in range(N) if i != j]
    for comb in itertools.combinations(edges_i, len(edges_i) - 3 + 1):
        solver.add_clause([c for c in comb])
    for comb in itertools.combinations(edges_i, 3 + 1):
        solver.add_clause([-c for c in comb])

def find_short_cycles(edges):
    adj = collections.defaultdict(list)
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    cycles = []
    for start in range(N):
        # BFS to find cycles
        queue = collections.deque([(start, [start])])
        while queue:
            curr, path = queue.popleft()
            if len(path) > 6:
                continue
            for nxt in adj[curr]:
                if nxt == start and len(path) >= 3:
                    cycles.append(path)
                elif nxt not in path:
                    queue.append((nxt, path + [nxt]))
    return cycles

iteration = 0
while True:
