def get_girth(adj):
    min_cycle = float('inf')
    for start in range(24):
        dist = {start: 0}
        parent = {start: -1}
        queue = collections.deque([start])
        while queue:
            curr = queue.popleft()
            for nxt in adj[curr]:
                if nxt not in dist:
                    dist[nxt] = dist[curr] + 1
                    parent[nxt] = curr
                    queue.append(nxt)
                elif parent[curr] != nxt:
                    min_cycle = min(min_cycle, dist[curr] + dist[nxt] + 1)
    return min_cycle

print("Girth:", get_girth(adj))
